"""Les a priori des θ tirés de la littérature publiée (but 23, D-424).

L'histoire budgétaire agrégée n'identifie aucun θ (D-421, D-423) : ce qui les porte est
l'a priori. D-417 en donnait un seul, le même pour tous, gaussien en ½ d'écart-type ½ ;
celui-ci en donne un par θ, pris dans une estimation publiée du paramètre du bloc
(`parametres/a_priori.yaml`, chaque nombre avec sa source, sa page, son tableau).

LA LOI SUR θ. Une estimation m du paramètre, d'écart-type s, passe par l'application
θ → paramètre du bloc, linéaire par morceaux par le centre (bas à θ = 0, centre à ½, haut
à 1, `predictif.theta.value_at`), prolongée au-delà des bornes par la pente de sa
moitié. Son inverse θ(v) donne :

    μ = θ(m),   s₋ = μ − min(θ(m − s), θ(m + s)),   s₊ = max(θ(m − s), θ(m + s)) − μ

et la loi de θ est une normale à deux écarts-types, s₋ sous μ, s₊ au-dessus (exacte quand
m est au centre, où l'application change de pente ; approchée sinon). μ peut sortir de
[0 ; 1] quand la source sort de la plage : la plage ne change pas (les études et les
curseurs la lisent), l'estimation reste dans la boîte, et l'a priori la pousse vers la
borne ; la D-entrée le dit. Un θ sans source garde la loi large de D-417, N(½ ; ½).

Les plages ne sont pas recopiées : `plages` les lit dans les paramètres des blocs.

UNE LOI TIRÉE DES DONNÉES. Celle de b (`jumeau_salaires_chomage`) n'est plus la seule
littérature : depuis D-438, la décision du propriétaire du 15 novembre 2026 sur D-435, la
courbe des salaires du panneau W1 (Urssaf et chômage localisé de l'Insee) combinée à la
méta-analyse de Nijkamp et Poot par leurs précisions, 0,210 ± 0,091, sur la plage
(0 ; 0,20 ; 1) : μ = 0,506, s₋ = 0,210, s₊ = 0,057 sur θ. Les deux composantes sont dans
le YAML (`panel`, `meta_analyse`) ; `lois` ne lit que leur combinaison.
"""

from __future__ import annotations

import functools
import math
from collections.abc import Mapping
from dataclasses import dataclass
from pathlib import Path
from typing import Any

import numpy as np
import yaml

FICHIER = Path(__file__).parent / "parametres" / "a_priori.yaml"


class APrioriError(ValueError):
    """Un a priori mal formé, ou un θ du registre sans entrée."""


@dataclass(frozen=True)
class Loi:
    """Une normale à deux écarts-types sur θ."""

    moyenne: float
    ecart_bas: float
    ecart_haut: float
    source: str | None = None
    """None : l'a priori large de D-417, sans source."""

    def __post_init__(self) -> None:
        if not (math.isfinite(self.moyenne) and self.ecart_bas > 0 and self.ecart_haut > 0):
            raise APrioriError(f"loi ({self.moyenne}, {self.ecart_bas}, {self.ecart_haut})")

    @property
    def ecart_type(self) -> float:
        """L'écart-type résumé, la moyenne des deux demi-écarts."""
        return 0.5 * (self.ecart_bas + self.ecart_haut)

    def residu(self, theta: Any) -> np.ndarray:
        """(θ − μ) / s±, le terme de l'a priori dans les moindres carrés."""
        t = np.asarray(theta, dtype=float)
        return (t - self.moyenne) / np.where(t < self.moyenne, self.ecart_bas,
                                             self.ecart_haut)


#: L'a priori de D-417 : gaussien en ½, d'écart-type ½.
LARGE = Loi(0.5, 0.5, 0.5)


def theta_de(valeur: float, plage: tuple[float, float, float]) -> float:
    """L'inverse de l'application θ → paramètre (bas, centre, haut), prolongée au-delà des
    bornes par la pente de la moitié qui y mène. La plage peut décroître (une montée en
    charge plus courte est une réponse plus forte)."""
    bas, centre, haut = plage
    if (valeur - centre) * (haut - centre) >= 0:
        if haut == centre:
            raise APrioriError(f"plage {plage} plate au-dessus du centre")
        return 0.5 + 0.5 * (valeur - centre) / (haut - centre)
    if bas == centre:
        raise APrioriError(f"plage {plage} plate au-dessous du centre")
    return 0.5 - 0.5 * (valeur - centre) / (bas - centre)


def loi_depuis(estimation: float, ecart_type: float, plage: tuple[float, float, float],
               source: str | None = None) -> Loi:
    """La loi de θ d'une estimation publiée du paramètre (docstring du module)."""
    if not ecart_type > 0:
        raise APrioriError(f"écart-type {ecart_type}")
    mu = theta_de(estimation, plage)
    a, b = theta_de(estimation - ecart_type, plage), theta_de(estimation + ecart_type, plage)
    return Loi(mu, mu - min(a, b), max(a, b) - mu, source)


def plages() -> dict[str, tuple[float, float, float]]:
    """La plage (bas, centre, haut) du paramètre de chaque θ estimé sur une source, lue
    dans les paramètres des blocs."""
    from impots.jumeau import thetas
    from impots.jumeau.blocs import commerce, menages, valeurs_entreprises

    c, m, e = commerce.charger(), menages.charger(), valeurs_entreprises.charger()

    def triple(d: Mapping[str, Any]) -> tuple[float, float, float]:
        return (float(d["low"]), float(d["central"]), float(d["high"]))

    def plage(p: Any) -> tuple[float, float, float]:
        return (p.bas, p.centre, p.haut)

    out = {thetas.ELASTICITE_PRIX_EXPORTATIONS.cle: c.bornes_x,
           thetas.ELASTICITE_PRIX_IMPORTATIONS.cle: c.bornes_m,
           thetas.EMPLOI_COUT: triple(m.sigma),
           thetas.SALAIRES_CHOMAGE: triple(m.echelle_chomage),
           "investissement_cout_capital": plage(e.elasticite_cout),
           "elasticite_creations": plage(e.elasticite),
           "investissement_accelerateur": plage(e.accelerateur_contemporain),
           "implantation_tmee": plage(e.semi_elasticite_tmee)}
    for ligne in m.offre.values():
        if ligne["un"] != "high":
            raise APrioriError(f"{ligne['cle']} : θ = 1 n'est pas la borne haute")
        out[ligne["cle"]] = triple(ligne)
    return out


@functools.cache
def lire(chemin: Path = FICHIER) -> dict[str, dict[str, Any]]:
    return yaml.safe_load(chemin.read_text(encoding="utf-8"))


def lois(chemin: Path = FICHIER) -> dict[str, Loi]:
    """Une loi par θ du registre ; un θ du registre sans entrée, ou une entrée hors du
    registre, est refusé par son nom."""
    from impots.jumeau import thetas

    entrees = lire(chemin)
    manquants = sorted(set(thetas.REGISTRE) - set(entrees))
    inconnus = sorted(set(entrees) - set(thetas.REGISTRE))
    if manquants or inconnus:
        raise APrioriError(f"θ sans a priori : {manquants} ; a priori sans θ : {inconnus}")
    bornes = plages()
    out = {}
    for cle, d in entrees.items():
        if "sans_source" in d:
            out[cle] = LARGE
        elif "theta" in d:
            t = d["theta"]
            out[cle] = Loi(float(t["moyenne"]), float(t["ecart_type"]),
                           float(t["ecart_type"]), d["source"])
        else:
            if cle not in bornes:
                raise APrioriError(f"« {cle} » : une estimation, mais aucune plage lue")
            out[cle] = loi_depuis(float(d["estimation"]), float(d["ecart_type"]),
                                  bornes[cle], d["source"])
    return out

fichiers.impots/jumeau/comparaison.py:
"""Le modèle structurel complet à côté des variantes publiées de Mésange (D-411).

UNE COMPARAISON DE COHÉRENCE, PAS UN JUGE. Mésange (Insee et DG Trésor, G2017-04, §4)
publie, pour un choc permanent d'un point de PIB ex ante, l'écart au compte central du PIB
en volume, de l'emploi salarié marchand et du solde primaire des APU. Le mode structurel
du jumeau (`blocs.ordre_structurel`, sans `mesange`) porte les mêmes canaux par ses
équations ; ses réponses se mettent à côté, à θ½, l'écart dit et expliqué, jamais forcé :
aucun paramètre n'est réglé dessus, et rien n'est préenregistré.

LES VARIANTES, dans la convention expansionniste de `macro.mesange` (une hausse de TVA
publiée se lit comme une baisse, par la linéarité de Mésange). Chaque année t, le choc
vaut un point du PIB de référence Y_t (`Tendance.chemin`), X_t = 0,01 Y_t :

* `impot_sur_le_revenu` : l'IR baisse de X_t (D5 des APU), réparti entre les déciles au
  prorata de l'IR des cellules (Mésange : une baisse uniforme du taux apparent, p. 118) ;
* `cotisations_employeurs` : les cotisations employeurs baissent de X_t (D61 des APU, et
  le signal des cotisations patronales du lot 2) ; aucun choc direct aux ménages ;
* `tva` : la TVA des ménages baisse de X_t net (D2 ; le point net de Mésange, p. 113, comme
  `macro.mesange.COUT_CHIFFRE`), répartie au prorata de la TVA des cellules ;
* `investissement_public` : la FBCF des APU monte de X_t (P51g), en valeur ;
* `depense_publique` : X_t réparti comme Mésange le compose (p. 106) : 8 % de FBCF, 25 % de
  rémunérations, 9 % de prestations en nature, 12 % de consommations intermédiaires, 46 %
  de prestations en espèces, celles-ci aux déciles au prorata des pensions, des allocations
  chômage et des prestations des cellules.

LES LIGNES, à 1, 2, 5 et 10 ans : le PIB en volume (l'indice chaîné de
`croissance_volume_pib`, variante sur référence, en %), l'emploi salarié marchand (en
milliers ; le bloc `emploi` écrit l'écart de l'emploi marchand), le solde primaire des APU
(en points de PIB : variante moins référence du solde sur le PIB) et, depuis D-414,
l'investissement des entreprises (la FBCF des SNF, en %, en volume : le bloc
`investissement` écrit des volumes aux prix du scénario ; Mésange imprime les SNF et EI) ;
depuis D-418, le taux de chômage (en points : variante moins référence de U / PA) et le
prix de la consommation des ménages (en %, le déflateur chaîné). L'emploi salarié
marchand est l'emploi salarié moins l'emploi public que le bloc `emploi_public` y met
(D-418). Mésange imprime ces deux lignes dans chaque tableau ; `macro.mesange.printed_row`
les lit sur la page de la variante.

LA VARIANTE SALARIALE DE MÉSANGE (D-349) : pour l'IR, les cotisations employeurs et la
TVA, Mésange imprime aussi le PIB sous une autre formation des salaires (Phillips, ou un
super-brut visé), à 1, 5 et 10 ans (`macro.mesange.sensibilite_salariale`) ; elle se met
à côté, comme référence de la sensibilité du PIB à la boucle prix-salaires.
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from typing import Any

import numpy as np

from impots.jumeau import thetas
from impots.jumeau.blocs import ordre_structurel
from impots.jumeau.blocs.tendance import Tendance
from impots.jumeau.mesures import HYPOTHESE, Mesure
from impots.jumeau.pas import Entrees
from impots.jumeau.trajectoire import Trajectoire, calculer
from impots.macro.mesange import HORIZONS as HORIZONS_MESANGE
from impots.macro.mesange import printed_row

VARIANTES = ("impot_sur_le_revenu", "cotisations_employeurs", "tva",
             "investissement_public", "depense_publique")
HORIZONS = (1, 2, 5, 10)
LIGNES = {"pib": ("gdp", "PIB en volume, %"),
          "emploi": ("emploi_milliers", "emploi salarié marchand, milliers"),
          "chomage": ("Taux de chômage", "taux de chômage, points"),
          "solde": ("solde_primaire_pts_pib", "solde primaire des APU, points de PIB"),
          "prix": ("Prix de la consommation des ménages",
                   "prix de la consommation des ménages, %"),
          "investissement": ("investissement_entreprises",
                             "investissement des entreprises, %")}
#: La composition de la variante de dépense publique (Mésange G2017-04, p. 106).
COMPOSITION_DEPENSE = {"apu_d_p51g": 0.08, "apu_d_d1": 0.25, "apu_d_d632": 0.09,
                       "apu_d_p2": 0.12, "apu_d_d62": 0.46}


def _parts(valeurs: np.ndarray) -> list[float]:
    total = float(np.sum(valeurs))
    if total <= 0:
        raise ValueError("une clé de répartition entre les déciles de somme nulle")
    return [float(v) / total for v in valeurs]


def mesure(variante: str, pib: Sequence[float], annees: Sequence[int],
           cellules: Any) -> Mesure:
    """La variante d'un point de PIB ex ante, chaque année, en loi hypothétique."""
    x = {a: 0.01 * y for a, y in zip(annees, pib, strict=True)}
    menages: dict[int, Any] | None = None
    entreprises: dict[int, Any] | None = None
    if variante == "impot_sur_le_revenu":
        chocs = {a: {"apu_r_d5": v} for a, v in x.items()}
        impulsions = {a: {"impot_sur_le_revenu": v} for a, v in x.items()}
        cle = _parts(cellules.par_decile("ir"))
        menages = {a: {"deciles": [v * c for c in cle]} for a, v in x.items()}
    elif variante == "cotisations_employeurs":
        chocs = {a: {"apu_r_d61": v} for a, v in x.items()}
        impulsions = {a: {"cotisations_employeurs": v} for a, v in x.items()}
        entreprises = {a: {"cotisations_employeurs": -v} for a, v in x.items()}
    elif variante == "tva":
        chocs = {a: {"apu_r_d2": v} for a, v in x.items()}
        impulsions = {a: {"tva": v} for a, v in x.items()}
        cle = _parts(cellules.par_decile("tva"))
        menages = {a: {"deciles": [v * c for c in cle]} for a, v in x.items()}
    elif variante == "investissement_public":
        chocs = {a: {"apu_d_p51g": v} for a, v in x.items()}
        impulsions = {a: {"investissement_public": v} for a, v in x.items()}
    elif variante == "depense_publique":
        chocs = {a: {c: p * v for c, p in COMPOSITION_DEPENSE.items()}
                 for a, v in x.items()}
        impulsions = {a: {"depense_publique": v} for a, v in x.items()}
        cle = _parts(sum(cellules.par_decile(n) for n in
                         ("retraite", "chomage_brut", "prestations")))
        menages = {a: {"deciles": [COMPOSITION_DEPENSE["apu_d_d62"] * v * c for c in cle]}
                   for a, v in x.items()}
    else:
        raise ValueError(f"variante « {variante} » inconnue ({VARIANTES})")
    return Mesure(identifiant=variante, libelle=f"Variante de Mésange : {variante}",
                  auteur="comparaison à Mésange", origine=HYPOTHESE, annees=tuple(annees),
                  chocs=chocs, impulsions=impulsions, menages=menages,
                  entreprises=entreprises)


def _chaine(traj: Trajectoire, champ: str) -> np.ndarray:
    """L'écart en % d'un niveau chaîné : la croissance (ou le déflateur de l'année sur
    l'année précédente) cumulée, variante sur référence."""
    ref, var = traj.niveaux(champ)
    return 100.0 * (np.cumprod(var[:, 0]) / np.cumprod(ref[:, 0]) - 1.0)


def reponses(traj: Trajectoire) -> dict[str, np.ndarray]:
    """Les lignes, par année, au premier tirage."""
    g_ref, g_var = traj.niveaux("croissance_volume_pib")
    volume = np.cumprod(1.0 + g_var[:, 0]) / np.cumprod(1.0 + g_ref[:, 0]) - 1.0
    sp_ref, sp_var = traj.niveaux("solde_primaire")
    y_ref, y_var = traj.niveaux("pib")
    i_ref, _ = traj.niveaux("fbcf_snf")
    u_ref, u_var = traj.niveaux("chomage")
    pa_ref, pa_var = traj.niveaux("population_active")
    emploi = traj.difference("emploi_salarie")[:, 0]
    if all(e.present("emploi_public") for e in traj.variante):
        emploi = emploi - traj.difference("emploi_public")[:, 0]
    return {"pib": 100.0 * volume,
            "emploi": emploi,
            "chomage": 100.0 * (u_var[:, 0] / pa_var[:, 0] - u_ref[:, 0] / pa_ref[:, 0]),
            "solde": 100.0 * (sp_var[:, 0] / y_var[:, 0] - sp_ref[:, 0] / y_ref[:, 0]),
            "prix": _chaine(traj, "prix_c_menages"),
            "investissement": 100.0 * traj.difference("fbcf_snf")[:, 0] / i_ref[:, 0]}


def publiee(variante: Any, ligne: str, horizon: int) -> float:
    """La ligne de Mésange à l'horizon : une ligne de `macro.mesange.ROWS` par sa clé, une
    autre par le libellé que le tableau imprime (`macro.mesange.printed_row`)."""
    cle = LIGNES[ligne][0]
    if cle in variante.rows:
        return float(variante.at(cle, str(horizon)))
    return float(printed_row(variante, cle)[HORIZONS_MESANGE.index(str(horizon))])


def comparer(depart: Any, entrees: Entrees, population: Any, cellules: Any, *,
             publiees: Mapping[str, Any], theta: float = 0.5,
             variantes: Sequence[str] = VARIANTES, **options: Any
             ) -> dict[str, dict[str, list[tuple[float, float]]]]:
    """{variante: {ligne: [(jumeau, Mésange) à chaque horizon]}} ; `publiees` les
    variantes lues par `macro.mesange.load`."""
    tendance = Tendance(depart)
    pib = [tendance.chemin(entrees, k)[0] for k in range(len(entrees.annees))]
    out: dict[str, dict[str, list[tuple[float, float]]]] = {}
    for v in variantes:
        blocs, boucles = ordre_structurel(depart, population, cellules, **options)
        m = mesure(v, pib, entrees.annees, cellules)
        traj = calculer(depart, entrees=entrees, mesures=[m],
                        theta=dict.fromkeys(thetas.REGISTRE, theta), blocs=blocs,
                        boucles=boucles)
        r = reponses(traj)
        out[v] = {ligne: [(float(r[ligne][h - 1]), publiee(publiees[v], ligne, h))
                          for h in HORIZONS] for ligne in LIGNES}
    return out

fichiers.impots/jumeau/etat.py:
"""L'état de l'économie pour une année (CADRE.md §2) : les valeurs, le masque des
absents, les contributions par origine et par mesure.

UN CHAMP NON CALCULÉ EST ABSENT, PAS NUL. L'état ne connaît que les champs qu'on y a
écrits ; lire un autre champ lève `ChampAbsent`, qui le nomme. Aucun NaN ne circule.

UNE CONTRIBUTION EST ADDITIVE ET GARDÉE À PART. Un champ additif est la somme de ses
contributions, chacune rangée sous sa clé (origine, mesure) : l'origine est le bloc qui
l'a écrite (ou « depart », « publie »), la mesure son identifiant (« » pour aucune). Un
champ non additif (un ratio, un indice de prix) a une valeur et un seul écrivain.

Chaque valeur est un tableau numpy de forme (n,), n le nombre de tirages.

LA SOMME D'UN CHAMP ADDITIF SE FAIT À LA LECTURE (D-411) : une écriture garde sa
contribution et marque le champ ; sa valeur est recalculée la première fois qu'on la lit,
dans l'ordre des contributions, comme avant (le même nombre au bit près). Les
contributions sont indexées par origine, pour que le point fixe retire celles d'un bloc
sans parcourir tout l'état. C'est de la plomberie : aucun nombre ne change.
"""

from __future__ import annotations

from collections.abc import Iterable, Mapping, Sequence

import numpy as np

from impots.jumeau.champs import champ as definition

Cle = tuple[str, str]
"""(origine, mesure)."""


class ChampAbsent(KeyError):
    """Un champ que personne n'a écrit, lu comme s'il existait."""

    def __str__(self) -> str:
        return str(self.args[0]) if self.args else "champ absent"


class EtatError(ValueError):
    """Une écriture que l'état refuse."""


class Etat:
    """Une année de l'économie, sur n tirages."""

    __slots__ = ("_origines", "_sales", "annee", "contributions", "n", "publie", "valeurs")

    def __init__(self, annee: int, n: int, *, publie: bool = False) -> None:
        if n < 1:
            raise EtatError(f"n = {n} tirage(s) : au moins un")
        self.annee = int(annee)
        self.n = int(n)
        self.publie = publie
        """Vrai pour un état lu dans les tables publiées (`historique`)."""
        self.valeurs: dict[str, np.ndarray] = {}
        self.contributions: dict[str, dict[Cle, np.ndarray]] = {}
        self._sales: set[str] = set()
        """Les champs additifs dont la somme est à refaire."""
        self._origines: dict[str, set[str]] = {}
        """origine → les champs où elle a une contribution."""

    # ----------------------------------------------------------------- lecture
    def __getitem__(self, nom: str) -> np.ndarray:
        if nom in self._sales:
            self._sales.discard(nom)
            self.valeurs[nom] = _somme(self.contributions[nom].values(), self.n)
        try:
            return self.valeurs[nom]
        except KeyError:
            definition(nom)
            raise ChampAbsent(f"champ « {nom} » absent en {self.annee} : personne ne l'a "
                              f"écrit, et il n'est pas nul") from None

    def present(self, nom: str) -> bool:
        return nom in self.valeurs

    def de(self, nom: str) -> dict[Cle, np.ndarray]:
        """Les contributions d'un champ additif, par (origine, mesure)."""
        if nom not in self.valeurs:
            self[nom]
        if not definition(nom).additif:
            raise EtatError(f"« {nom} » n'est pas additif : il n'a pas de contributions")
        return self.contributions[nom]

    def par_mesure(self, nom: str) -> dict[str, np.ndarray]:
        """Les contributions d'un champ sommées par mesure, toutes origines."""
        out: dict[str, np.ndarray] = {}
        for (_, mesure), valeur in self.de(nom).items():
            out[mesure] = out[mesure] + valeur if mesure in out else valeur
        return out

    def champs(self) -> tuple[str, ...]:
        return tuple(self.valeurs)

    # ----------------------------------------------------------------- écriture
    def _tableau(self, valeur: object, nom: str) -> np.ndarray:
        if type(valeur) is np.ndarray and valeur.dtype == np.float64 \
                and valeur.shape == (self.n,):
            tableau = valeur  # ce que `np.asarray(valeur, dtype=float)` rendrait
        else:
            tableau = np.asarray(valeur, dtype=float)
            if tableau.ndim == 0:
                tableau = np.full(self.n, float(tableau))
            if tableau.shape != (self.n,):
                raise EtatError(f"« {nom} » de forme {tableau.shape}, attendu ({self.n},)")
        if not np.isfinite(tableau).all():
            raise EtatError(f"« {nom} » non fini en {self.annee} : aucun NaN ne circule")
        return tableau

    def ecrire(self, nom: str, cle: Cle, valeur: object) -> None:
        """Ajoute (ou remplace) la contribution `cle` d'un champ additif."""
        if not definition(nom).additif:
            raise EtatError(f"« {nom} » n'est pas additif : `fixer`, pas `ecrire`")
        parts = self.contributions.get(nom)
        if parts is None:
            parts = self.contributions[nom] = {}
        parts[cle] = self._tableau(valeur, nom)
        self._marquer(nom, (cle,))

    def ecrire_origine(self, origine: str, nom: str, parts: Mapping[str, object]) -> list:
        """Les contributions (origine, mesure) d'un champ additif, d'un coup ; rend les
        tableaux écrits, dont l'appelant vérifie qu'ils sont finis (`verifier_finis`) :
        le chemin rapide de `ecrire`, pour un bloc qui écrit tout un champ (D-411)."""
        contributions = self.contributions.get(nom)
        if contributions is None:
            contributions = self.contributions[nom] = {}
        if nom not in self.valeurs:
            self.valeurs[nom] = _VIDE
        self._sales.add(nom)
        champs = self._origines.get(origine)
        if champs is None:
            self._origines[origine] = {nom}
        else:
            champs.add(nom)
        n = (self.n,)
        ecrits = []
        for mesure, valeur in parts.items():
            if type(valeur) is np.ndarray and valeur.dtype == np.float64 \
                    and valeur.shape == n:
                tableau = valeur
            else:
                tableau = np.asarray(valeur, dtype=float)
                if tableau.ndim == 0:
                    tableau = np.full(self.n, float(tableau))
                if tableau.shape != n:
                    raise EtatError(f"« {nom} » de forme {tableau.shape}, attendu "
                                    f"({self.n},)")
            contributions[(origine, mesure)] = tableau
            ecrits.append(tableau)
        return ecrits

    def verifier_finis(self, noms: Sequence[str], tableaux: Sequence[list]) -> None:
        """Aucun NaN ne circule : les tableaux écrits par `ecrire_origine`, d'un seul
        test ; le premier champ fautif nommé."""
        tous = [t for liste in tableaux for t in liste]
        if tous and not np.isfinite(np.concatenate(tous)).all():
            for nom, liste in zip(noms, tableaux, strict=True):
                if any(not np.isfinite(t).all() for t in liste):
                    raise EtatError(f"« {nom} » non fini en {self.annee} : aucun NaN ne "
                                    f"circule")

    def _marquer(self, nom: str, cles: Iterable[Cle]) -> None:
        if nom not in self.valeurs:
            self.valeurs[nom] = _VIDE
        self._sales.add(nom)
        for origine, _ in cles:
            champs = self._origines.get(origine)
            if champs is None:
                self._origines[origine] = {nom}
            else:
                champs.add(nom)

    def declarer(self, nom: str) -> None:
        """Rend présent un champ additif qu'un bloc écrit sans contribution cette année :
        calculé nul, pas absent (le bloc a tourné)."""
        if nom not in self.valeurs:
            if not definition(nom).additif:
                raise EtatError(f"« {nom} » n'est pas additif")
            self.contributions[nom] = {}
            self.valeurs[nom] = np.zeros(self.n)

    def retirer(self, origine: str) -> None:
        """Retire toutes les contributions d'une origine (une itération du point fixe)."""
        for nom in self._origines.pop(origine, ()):
            parts = self.contributions[nom]
            for c in [c for c in parts if c[0] == origine]:
                del parts[c]
            self._sales.add(nom)

    def fixer(self, nom: str, valeur: object) -> None:
        """La valeur d'un champ non additif."""
        if definition(nom).additif:
            raise EtatError(f"« {nom} » est additif : il s'écrit par contributions")
        self.valeurs[nom] = self._tableau(valeur, nom)

    def copier_contributions(self, nom: str, source: Mapping[Cle, np.ndarray]) -> None:
        ancien = self.contributions.get(nom, {})
        for origine in {c[0] for c in ancien}:
            self._origines.get(origine, set()).discard(nom)
        self.contributions[nom] = {c: v for c, v in source.items()}
        self._marquer(nom, self.contributions[nom])


#: La valeur d'un champ additif écrit, que sa première lecture calculera.
_VIDE = np.zeros(0)


def _somme(valeurs: Iterable[np.ndarray], n: int) -> np.ndarray:
    total = np.zeros(n)
    for v in valeurs:
        total = total + v
    return total

