"""Le compte des APU par sous-secteur, et la compensation (D-481).

LE COMPTE CONSOLIDÉ NE CHANGE PAS. Ce module lit une trajectoire du jumeau (la
référence et la variante, `trajectoire.calculer`) et la répartit, année par année, entre
l'État (S13111), les ODAC (S13112), les APUL (S1313) et les ASSO (S1314) ; dans les ASSO,
l'écart d'une mesure se range par branche. Il n'écrit rien dans l'état du jumeau.

LES IDENTITÉS (vérifiées à chaque année, 1e-9 du PIB, sur chaque tirage, `verifier`) :

1. Σ_s recettes_s = recettes des APU (hors intérêts) ; Σ_s dépenses_s = dépenses
   primaires ; Σ_s intérêts nets_s = intérêts nets ;
2. Σ_s transferts reçus_s = Σ_s transferts versés_s (les transferts entre APU, D73, D9 et
   la compensation, se consolident) ;
3. B9_s = recettes_s + reçus_s − dépenses_s − versés_s − intérêts_s, et Σ_s B9_s = B9 ;
4. D_s,t = D_s,t−1 − B9_s,t + A_s,t, et Σ_s D_s = D (A : l'ajustement flux-stocks et
   les écarts de publication du jumeau, nuls en projection, aux parts de la dette) ;
5. dans les ASSO, la somme des écarts des branches est l'écart des ASSO.

Sur les comptes publiés de 2025 (`financement_sous_secteurs.yaml`), la somme des quatre
sous-secteurs redonne chaque ligne de la t. 3.201 à 5e-4 Md€ près, hors D41, D73 et D9,
consolidées entre sous-secteurs, dont la consolidation est la même en recettes et en
dépenses (143,072 Md€ de D73, 30,578 de D9, 0,880 de D41) : B9 se somme exactement.

LA RÉPARTITION (des conventions, chacune dite) :

* la référence : chaque ligne du compte consolidé aux parts de ses sous-secteurs en 2025
  (t. 3.203 à 3.212) ; les transferts entre APU de 2025 suivent le PIB nominal ; les
  intérêts nets aux parts de 2025 ; la dette d'ouverture aux parts de fin 2025 ;
* l'écart d'une mesure : son choc statique (les contributions du bloc `mesures`) au
  payeur que disent ses instruments (`Mesure.impulsions`, `financement.yaml`), le reste
  au prorata de la ligne ; les effets induits (les autres blocs) aux parts de leur ligne,
  et ceux qu'un bloc ne ventile pas (`solde_induit`) à la clé des prélèvements ; les
  intérêts de l'écart au prorata de la dette accumulée de chaque compte ;
* la compensation (CSS, L131-7) : la perte de recette d'une branche sur un instrument
  compensable est payée par l'État, en transfert, au taux de l'option de la branche
  (compensée 1, non compensée 0, θ quand l'issue est incertaine).
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from dataclasses import dataclass, field
from functools import cache
from pathlib import Path
from typing import Any

import numpy as np
import yaml

from impots.jumeau.champs import DEPENSES, RECETTES

PARAMS = Path(__file__).resolve().parents[1] / "parametres"
SECTEURS = ("etat", "odac", "apul", "asso")
TOLERANCE = 1e-9
OPTIONS = ("compensee", "non_compensee", "theta")
#: Les champs du compte que le jumeau écrit sans ligne publiée.
NON_VENTILES = ("solde_induit", "mesures_non_ventilees")


class FinancementError(ValueError):
    """Une répartition que le module refuse."""


@cache
def parametres() -> dict[str, Any]:
    p = yaml.safe_load((PARAMS / "financement.yaml").read_text(encoding="utf-8"))
    p["publie"] = yaml.safe_load((PARAMS / "financement_sous_secteurs.yaml")
                                 .read_text(encoding="utf-8"))
    return p


def branches() -> tuple[str, ...]:
    return tuple(parametres()["branches"])


def comptes() -> tuple[str, ...]:
    """Les comptes de l'écart : trois sous-secteurs, puis les branches des ASSO."""
    return ("etat", "odac", "apul", *(f"asso.{b}" for b in branches()))


def secteur(compte: str) -> str:
    return compte.split(".")[0]


# --------------------------------------------------------------------- les clés
def _normer(poids: Mapping[str, float]) -> dict[str, float]:
    """Des poids en parts qui somment à 1 au bit : la dernière part est le complément."""
    total = sum(poids.values())
    if total == 0:
        raise FinancementError(f"clé de somme nulle : {dict(poids)}")
    cles = list(poids)
    out = {c: poids[c] / total for c in cles[:-1]}
    out[cles[-1]] = 1.0 - sum(out.values())
    return out


def parts_ligne(nom: str) -> dict[str, float]:
    """Les parts des sous-secteurs dans une ligne du compte, en 2025 (brutes de la
    consolidation : la part externe et la part entre APU se répartissent pareil)."""
    lignes = parametres()["publie"]["lignes"]
    if nom in NON_VENTILES:
        return cle_prelevements()
    if nom not in lignes:
        raise FinancementError(f"ligne « {nom} » sans parts publiées")
    ligne = lignes[nom]
    poids = {s: float(ligne[s]) for s in SECTEURS}
    if sum(poids.values()) == 0:
        return cle_prelevements() if nom.startswith("apu_r") else cle_depenses()
    return _normer(poids)


@cache
def cle_prelevements() -> dict[str, float]:
    """Les impôts et cotisations reçus par sous-secteur en 2025 (D2, D5, D91, D733, D61,
    D995), la clé des effets induits que les blocs ne ventilent pas."""
    lignes = parametres()["publie"]["lignes"]
    noms = ("apu_r_d2", "apu_r_d5", "apu_r_d91", "apu_r_d733", "apu_r_d61", "apu_r_d995")
    return _normer({s: sum(float(lignes[n][s]) for n in noms) for s in SECTEURS})


@cache
def cle_depenses() -> dict[str, float]:
    """Les dépenses primaires hors transferts entre APU, par sous-secteur, en 2025."""
    lignes = parametres()["publie"]["lignes"]
    noms = [n for n in DEPENSES if n in lignes and n not in ("apu_d_d73", "apu_d_d9")]
    return _normer({s: sum(float(lignes[n][s]) for n in noms) for s in SECTEURS})


#: Les branches des fiches (`transmission.BRANCHES`) dont le compte porte un autre nom.
BRANCHE_COMPTE = {"vieillesse": "vieillesse_base", "chomage": "unedic",
                  "retraite_complementaire": "complementaires"}


def _payeurs_fiche(cle: str) -> dict[str, float | None]:
    """{compte : part dite par la fiche, ou None} des APU qui paient une mesure."""
    from impots.jumeau import transmission

    candidat, mesure = cle.split("/")
    out: dict[str, float | None] = {}
    for p in transmission.fiche(candidat, mesure)["payeurs"] or ():
        qui = str(p["qui"])
        if p["sens"] != "paie" or not qui.startswith("apu:"):
            continue
        compte = qui.removeprefix("apu:")
        if compte.startswith("secu:"):
            branche = compte.removeprefix("secu:")
            compte = f"asso.{BRANCHE_COMPTE.get(branche, branche)}"
        if compte not in comptes():
            raise FinancementError(f"{cle} : payeur « {qui} » sans compte ({comptes()})")
        part = p.get("part")
        out[compte] = (out.get(compte) or 0.0) + float(part) if part is not None else None
    if not out:
        raise FinancementError(f"{cle} : la fiche ne nomme aucune APU qui paie")
    return out


def payeurs_fiche(cle: str) -> tuple[str, ...]:
    """Les comptes des APU qui paient une mesure, lus dans sa fiche de transmission (le
    volet `carte`, `payeurs`, sens « paie ») : `apu:etat` → l'État, `apu:apul`, `apu:odac`,
    `apu:secu:<branche>` → la branche des ASSO (D-487 ; `vieillesse` → la CNAV et les
    régimes de base, `retraite_complementaire` → les complémentaires, `chomage` →
    l'Unédic, D-510)."""
    return tuple(_payeurs_fiche(cle))


def cle_reste(mesure: str | None, cote: str) -> dict[str, float]:
    """La clé du choc statique d'une mesure que ses impulsions ne portent pas (`reste`).
    Par défaut, la clé des prélèvements (recettes) ou des dépenses ; quand
    `financement.yaml` (`mesures.<mesure>.reste`) nomme une ligne du compte et la fiche
    de la mesure, les parts de cette ligne en 2025 restreintes aux payeurs que la fiche
    nomme, renormées (D-487 : le point d'indice, payé par l'État, les APUL et les
    hôpitaux, et non à la clé des prélèvements). Quand la fiche dit la part de chacun de
    ses payeurs, ce sont ces parts (D-510)."""
    propre = ((parametres().get("mesures") or {}).get(mesure or "") or {}).get("reste")
    if not propre:
        return _comme_comptes(cle_prelevements() if cote == "recettes" else cle_depenses())
    dites = _payeurs_fiche(propre["fiche"])
    if all(v is not None for v in dites.values()):
        # La fiche dit la part de chaque payeur (le volet `fiches`, D-504) : elle passe
        # avant les parts de la ligne (D-510). Une part nulle n'est pas un payeur.
        return _normer({cp: v for cp, v in dites.items() if v})
    parts = parts_ligne(propre["ligne"])
    payeurs = payeurs_fiche(propre["fiche"])
    poids = {cp: parts[secteur(cp)] for cp in payeurs}
    par_secteur: dict[str, int] = {}
    for cp in payeurs:
        par_secteur[secteur(cp)] = par_secteur.get(secteur(cp), 0) + 1
    # Deux branches des ASSO nommées : la part des ASSO se partage, faute de mieux, à parts
    # égales (dit) ; une seule : elle prend la part des ASSO.
    poids = {cp: v / par_secteur[secteur(cp)] for cp, v in poids.items()}
    return _normer(poids)


def _comme_comptes(parts: Mapping[str, float]) -> dict[str, float]:
    """Des parts par sous-secteur en parts par compte (les ASSO au non ventilé)."""
    return {("asso.asso_non_ventile" if s == "asso" else s): v for s, v in parts.items()}


def affectation(instrument: str, mesure: str | None, theta: Mapping[str, Any]
                ) -> dict[str, Any]:
    """{compte : part} d'un instrument pour une mesure. Une part peut être un tableau de
    tirages (un θ)."""
    p = parametres()
    propre = (p.get("mesures") or {}).get(mesure or "", {}).get(instrument)
    if propre is not None:
        out: dict[str, Any] = {}
        for compte, v in propre.items():
            if compte not in comptes():
                raise FinancementError(f"compte « {compte} » inconnu ({mesure})")
            if isinstance(v, str) and v.startswith("theta:"):
                out[compte] = valeur_theta(v.removeprefix("theta:"), theta)
            elif v != "reste":
                out[compte] = float(v)
        restes = [c for c, v in propre.items() if v == "reste"]
        if len(restes) > 1:
            raise FinancementError(f"deux « reste » pour {mesure}, {instrument}")
        if restes:
            out[restes[0]] = 1.0 - sum(out.values())
        return out
    if instrument not in p["instruments"]:
        raise FinancementError(f"instrument « {instrument} » sans payeur "
                               f"(financement.yaml, instruments)")
    a = p["instruments"][instrument]["affectation"]
    if a == "depenses":
        return _comme_comptes(cle_depenses())
    if isinstance(a, str) and a.startswith("ligne:"):
        return _comme_comptes(parts_ligne(a.removeprefix("ligne:")))
    for compte in a:
        if compte not in comptes():
            raise FinancementError(f"compte « {compte} » inconnu ({instrument})")
    return _normer({c: float(v) for c, v in a.items()})


def valeur_theta(cle: str, theta: Mapping[str, Any]) -> Any:
    """La valeur d'un θ du volet : a_zero + θ (a_un − a_zero). Un θ sans réglage est
    refusé, comme partout dans le jumeau."""
    ligne = parametres()["thetas"][cle]
    if cle not in theta:
        raise FinancementError(f"θ « {cle} » sans réglage : il n'a pas de défaut")
    t = np.asarray(theta[cle], dtype=float)
    return ligne["a_zero"] + t * (ligne["a_un"] - ligne["a_zero"])


def taux_compensation(compte: str, options: Mapping[str, str],
                      theta: Mapping[str, Any]) -> Any:
    """La part de la perte d'un compte des ASSO que l'État compense."""
    if not compte.startswith("asso."):
        return 0.0
    b = compte.removeprefix("asso.")
    option = options.get(b) or parametres()["compensation"]["defaut"][b]
    if option not in OPTIONS:
        raise FinancementError(f"option « {option} » inconnue ({OPTIONS})")
    if option == "compensee":
        return 1.0
    if option == "non_compensee":
        return 0.0
    return valeur_theta("financement_compensation", theta)


# --------------------------------------------------------------------- le compte
@dataclass
class CompteSousSecteurs:
    """Les postes par scénario (« reference », « variante », « ecart »), compte et année,
    chacun de forme (années, tirages). Les sous-secteurs ont les trois scénarios ; les
    branches des ASSO, l'écart seulement."""

    annees: tuple[int, ...]
    n: int
    postes: dict[tuple[str, str, str], np.ndarray] = field(default_factory=dict)
    compensation: dict[str, np.ndarray] = field(default_factory=dict)
    """Par compte des ASSO, le transfert de l'État de chaque année (Md€)."""
    residus: dict[str, float] = field(default_factory=dict)

    def get(self, scenario: str, compte: str, poste: str) -> np.ndarray:
        """Un poste ; un compte de l'écart qu'aucune mesure ne touche est nul."""
        cle = (scenario, compte, poste)
        if cle not in self.postes and scenario == "ecart":
            return np.zeros((len(self.annees), self.n))
        return self.postes[cle]

    def _ajouter(self, scenario: str, compte: str, poste: str, k: int, v: Any) -> None:
        cle = (scenario, compte, poste)
        if cle not in self.postes:
            self.postes[cle] = np.zeros((len(self.annees), self.n))
        self.postes[cle][k] += np.broadcast_to(np.asarray(v, dtype=float), (self.n,))


POSTES = ("recettes", "depenses", "transferts_recus", "transferts_verses",
          "interets_nets", "b9", "dette")


def _parts_dette() -> dict[str, float]:
    d = parametres()["publie"]["dette"]
    return _normer({s: float(d[s]) for s in SECTEURS})


def _parts_interets() -> dict[str, float]:
    lignes = parametres()["publie"]["lignes"]
    v, r = lignes["interets_verses"], lignes["interets_recus"]
    return _normer({s: float(v[s]) - float(r[s]) for s in SECTEURS})


def _repartir(total: Any, parts: Mapping[str, Any]) -> dict[str, Any]:
    """Un total en parts, la dernière en complément : la somme redonne le total au bit
    près quand les parts sont des scalaires."""
    cles = list(parts)
    out = {c: total * parts[c] for c in cles[:-1]}
    reste = total
    for v in out.values():
        reste = reste - v
    out[cles[-1]] = reste
    return out


def _statique(etat: Any, champs: Sequence[str]) -> dict[str, dict[str, np.ndarray]]:
    """{mesure : {champ : contribution}} du bloc `mesures` (le choc statique)."""
    out: dict[str, dict[str, np.ndarray]] = {}
    for nom in champs:
        if not etat.present(nom):
            continue
        for (origine, mesure), v in etat.de(nom).items():
            if origine == "mesures" and mesure:
                out.setdefault(mesure, {})[nom] = v
    return out


def _avec_publics(m: Any) -> dict[int, dict[str, float]]:
    """Les impulsions d'une mesure et les cotisations de la rémunération publique qu'elle
    porte à part (D-500) : le compte des sous-secteurs range les deux de la même façon."""
    out = {a: dict(v) for a, v in (m.impulsions or {}).items()}
    for a, v in (getattr(m, "prelevements_publics", None) or {}).items():
        for i, x in v.items():
            out.setdefault(a, {})[i] = out.get(a, {}).get(i, 0.0) + float(x)
    return out


def decomposer(traj: Any, mesures: Sequence[Any], theta: Mapping[str, Any] | None = None,
               options: Mapping[str, str] | None = None) -> CompteSousSecteurs:
    """Le compte par sous-secteur d'une trajectoire, et la compensation."""
    theta, options = dict(theta or {}), dict(options or {})
    publie = parametres()["publie"]
    annees = tuple(traj.annees)
    n = traj.reference[0].n
    c = CompteSousSecteurs(annees, n)
    impulsions = {m.identifiant: _avec_publics(m) for m in mesures}
    inter = {nom: float(publie["lignes"][nom]["consolidation"])
             for nom in ("apu_r_d73", "apu_r_d9", "apu_d_d73", "apu_d_d9")}
    pib0 = None
    instruments_comp = set(parametres()["compensation"]["instruments"])
    for k, annee in enumerate(annees):
        ref, var = traj.reference[k], traj.variante[k]
        if pib0 is None:
            pib0 = ref["pib"]
        g = ref["pib"] / pib0
        # ---- la référence, par sous-secteur
        for scen in ("reference", "variante"):
            for nom, cote in [(r, "recettes") for r in RECETTES] + [
                    (d, "depenses") for d in DEPENSES]:
                if not ref.present(nom):
                    continue
                for s, v in _repartir(ref[nom], parts_ligne(nom)).items():
                    c._ajouter(scen, s, cote, k, v)
            # les transferts entre APU de 2025, au PIB nominal (ils se consolident)
            for nom, cote in (("apu_r_d73", "transferts_recus"), ("apu_r_d9", "transferts_recus"),
                              ("apu_d_d73", "transferts_verses"),
                              ("apu_d_d9", "transferts_verses")):
                for s, v in _repartir(inter[nom] * g, parts_ligne(nom)).items():
                    c._ajouter(scen, s, cote, k, v)
            for s, v in _repartir(ref["interets_nets"], _parts_interets()).items():
                c._ajouter(scen, s, "interets_nets", k, v)
        # ---- l'écart, par compte
        statique = _statique(var, RECETTES + DEPENSES)
        for nom, cote in [(r, "recettes") for r in RECETTES] + [
                (d, "depenses") for d in DEPENSES]:
            delta = (var[nom] if var.present(nom) else 0.0) - (
                ref[nom] if ref.present(nom) else 0.0)
            if not np.any(delta):
                continue
            stat = sum((statique.get(m, {}).get(nom, 0.0) for m in statique), np.zeros(n))
            induit = delta - stat
            for s, v in _repartir(induit, _comme_comptes(parts_ligne(nom))).items():
                c._ajouter("ecart", s, cote, k, v)
        for m, champs in statique.items():
            for cote, noms in (("recettes", RECETTES), ("depenses", DEPENSES)):
                total = sum((v for nom, v in champs.items() if nom in noms), np.zeros(n))
                if not np.any(total):
                    continue
                imp = {i: float(x) for i, x in (impulsions.get(m, {}).get(annee) or {}).items()}
                # le signe : une impulsion est un coût (expansionniste) ; une recette
                # perdue, une dépense accrue. Les instruments de dépense vont aux
                # dépenses, les autres aux recettes.
                depense = {"depense_publique", "investissement_public"}
                du_cote = {i: (x if i in depense else -x) for i, x in imp.items()
                           if (i in depense) == (cote == "depenses")}
                reste = total - sum(du_cote.values(), 0.0)
                for i, montant in du_cote.items():
                    for compte, part in affectation(i, m, theta).items():
                        v = montant * part
                        c._ajouter("ecart", compte, cote, k, v)
                        if i in instruments_comp and compte.startswith("asso."):
                            perte = np.maximum(-np.broadcast_to(v, (n,)), 0.0)
                            t = perte * taux_compensation(compte, options, theta)
                            c._ajouter("ecart", "etat", "transferts_verses", k, t)
                            c._ajouter("ecart", compte, "transferts_recus", k, t)
                            c.compensation.setdefault(
                                compte, np.zeros((len(annees), n)))[k] += t
                for s, v in _repartir(reste, cle_reste(m, cote)).items():
                    c._ajouter("ecart", s, cote, k, v)
        # ---- les intérêts de l'écart, au prorata de la dette accumulée de chaque compte
        d_int = var["interets_nets"] - ref["interets_nets"]
        if k == 0:
            dettes = {cp: np.zeros(n) for cp in comptes()}
        else:
            dettes = {cp: c.get("ecart", cp, "dette")[k - 1] for cp in comptes()
                      if ("ecart", cp, "dette") in c.postes}
        total_d = sum(dettes.values(), np.zeros(n))
        sur = np.abs(total_d) > 1e-9
        for cp in comptes():
            part = np.where(sur, dettes.get(cp, np.zeros(n)) / np.where(sur, total_d, 1.0),
                            _comme_comptes(_parts_dette()).get(cp, 0.0))
            c._ajouter("ecart", cp, "interets_nets", k, d_int * part)
        # ---- B9 et dette des comptes de l'écart
        for cp in comptes():
            b9 = _b9(c, "ecart", cp, k)
            c._ajouter("ecart", cp, "b9", k, b9)
            prec = c.get("ecart", cp, "dette")[k - 1] if k else 0.0
            ajust = ((var["dette"] - var["dette_ouverture"] + var["b9"])
                     - (ref["dette"] - ref["dette_ouverture"] + ref["b9"]))
            c._ajouter("ecart", cp, "dette", k, prec - b9
                       + ajust * _comme_comptes(_parts_dette()).get(cp, 0.0))
        # ---- la variante des sous-secteurs : la référence plus les écarts de leurs comptes
        for cp in comptes():
            s = secteur(cp)
            for poste in ("recettes", "depenses", "transferts_recus", "transferts_verses",
                          "interets_nets"):
                cle = ("ecart", cp, poste)
                if cle in c.postes:
                    c._ajouter("variante", s, poste, k, c.postes[cle][k])
        for scen, etat in (("reference", ref), ("variante", var)):
            ajust = etat["dette"] - etat["dette_ouverture"] + etat["b9"]
            for s in SECTEURS:
                b9 = _b9(c, scen, s, k)
                c._ajouter(scen, s, "b9", k, b9)
                if k == 0:
                    prec = etat["dette_ouverture"] * _parts_dette()[s]
                else:
                    prec = c.get(scen, s, "dette")[k - 1]
                c._ajouter(scen, s, "dette", k, prec - b9 + ajust * _parts_dette()[s])
    for s in SECTEURS:
        for poste in POSTES:
            if ("reference", s, poste) in c.postes:
                c.postes[("ecart", s, poste)] = (c.get("variante", s, poste)
                                                 - c.get("reference", s, poste))
    c.residus = verifier(c, traj)
    return c


def _b9(c: CompteSousSecteurs, scen: str, compte: str, k: int) -> np.ndarray:
    def lu(p: str) -> np.ndarray:
        cle = (scen, compte, p)
        return c.postes[cle][k] if cle in c.postes else np.zeros(c.n)

    return (lu("recettes") + lu("transferts_recus") - lu("depenses")
            - lu("transferts_verses") - lu("interets_nets"))


class IdentiteSousSecteurs(FinancementError):
    """Une identité des sous-secteurs ne tient pas à 1e-9 du PIB."""


def verifier(c: CompteSousSecteurs, traj: Any) -> dict[str, float]:
    """Les identités du module (docstring), à 1e-9 du PIB sur chaque tirage ; rend le
    pire résidu relatif de chacune."""
    pire: dict[str, float] = {}

    def tenir(nom: str, residu: np.ndarray, pib: np.ndarray, annee: int) -> None:
        r = float(np.max(np.abs(residu / pib)))
        pire[nom] = max(pire.get(nom, 0.0), r)
        if r > TOLERANCE:
            raise IdentiteSousSecteurs(f"identité « {nom} » violée en {annee} : {r:.3e} "
                                       f"du PIB")

    for k, annee in enumerate(c.annees):
        for scen, etat in (("reference", traj.reference[k]), ("variante", traj.variante[k])):
            pib = etat["pib"]

            def somme(poste: str, scen: str = scen, k: int = k) -> np.ndarray:
                return sum((c.get(scen, s, poste)[k] for s in SECTEURS
                            if (scen, s, poste) in c.postes), np.zeros(c.n))

            tenir(f"{scen}.recettes", somme("recettes") - etat["apu_recettes"], pib, annee)
            tenir(f"{scen}.depenses", somme("depenses") - etat["apu_depenses_primaires"],
                  pib, annee)
            tenir(f"{scen}.interets", somme("interets_nets") - etat["interets_nets"], pib,
                  annee)
            tenir(f"{scen}.transferts", somme("transferts_recus")
                  - somme("transferts_verses"), pib, annee)
            tenir(f"{scen}.b9", somme("b9") - etat["b9"], pib, annee)
            tenir(f"{scen}.dette", somme("dette") - etat["dette"], pib, annee)
        pib = traj.variante[k]["pib"]
        for poste in POSTES:
            branches_asso = sum((c.get("ecart", cp, poste)[k] for cp in comptes()
                                 if cp.startswith("asso.") and ("ecart", cp, poste)
                                 in c.postes), np.zeros(c.n))
            if ("ecart", "asso", poste) in c.postes:
                tenir(f"branches.{poste}", branches_asso - c.get("ecart", "asso", poste)[k],
                      pib, annee)
    return pire


def resume(c: CompteSousSecteurs, tirage: int = 0) -> dict[str, Any]:
    """Les écarts par sous-secteur et par branche, année par année, en Md€ (un tirage)."""
    out: dict[str, Any] = {"annees": list(c.annees), "sous_secteurs": {}, "branches": {},
                           "compensation": {}, "residus": c.residus}
    for s in SECTEURS:
        out["sous_secteurs"][s] = {
            p: {"reference": [round(float(x), 3) for x in c.get("reference", s, p)[:, tirage]],
                "ecart": [round(float(x), 3) for x in c.get("ecart", s, p)[:, tirage]]}
            for p in ("b9", "dette")}
    for cp in comptes():
        if cp.startswith("asso.") and ("ecart", cp, "b9") in c.postes:
            out["branches"][cp] = {p: [round(float(x), 3) for x in
                                       c.get("ecart", cp, p)[:, tirage]]
                                   for p in ("recettes", "transferts_recus", "b9", "dette")}
    for cp, v in c.compensation.items():
        out["compensation"][cp] = [round(float(x), 3) for x in v[:, tirage]]
    return out

fichiers.impots/jumeau/identites.py:
"""Les identités vérifiées à chaque pas (CADRE.md §6), à 1e-9 du PIB, sur chaque tirage.

1. ``emplois`` — le PIB égale la somme signée de ses emplois (importations en moins),
   l'effet non ventilé, la ventilation et l'arrondi publiés compris ;
2. ``revenus`` — le PIB égale D1 + B2A3G + D2 − D3, l'effet non ventilé et l'arrondi
   publié compris ;
3. ``apu`` — les recettes et les dépenses primaires égalent la somme de leurs catégories,
   B9 = recettes − dépenses primaires − intérêts nets, et le solde primaire = B9 +
   intérêts nets ;
4. ``dette`` — D_t = D_{t−1} − B9_t + SFA_t (+ l'écart de millésime et l'arrondi publiés,
   nuls en projection) ; avec l'état précédent, la dette d'ouverture est sa dette ;
5. ``contributions`` — chaque champ additif égale la somme de ses contributions.

Une identité qui lit un champ absent REFUSE en le nommant (`IdentiteIncalculable`) : elle
ne le remplace pas par zéro. Une identité violée lève `IdentiteViolee`, qui dit laquelle,
l'année, le tirage et l'écart.
"""

from __future__ import annotations

from collections.abc import Callable

import numpy as np

from impots.jumeau.champs import DEPENSES, EMPLOIS, RECETTES, REGISTRE, REVENUS
from impots.jumeau.champs import champ as definition
from impots.jumeau.etat import ChampAbsent, Etat

TOLERANCE = 1e-9
"""En part du PIB, sur chaque tirage (§6)."""

IDENTITES = ("emplois", "revenus", "apu", "dette", "contributions")


class IdentiteIncalculable(ValueError):
    """Une identité lit un champ absent."""


class IdentiteViolee(ValueError):
    """Une identité ne tient pas à 1e-9 du PIB."""


def _lire(etat: Etat, nom: str, identite: str) -> np.ndarray:
    try:
        return etat[nom]
    except ChampAbsent:
        raise IdentiteIncalculable(
            f"identité « {identite} » en {etat.annee} : le champ « {nom} » est absent ; "
            f"elle ne le lit pas comme nul") from None


def _signee(etat: Etat, noms: tuple[str, ...], identite: str) -> np.ndarray:
    total = np.zeros(etat.n)
    for nom in noms:
        total = total + definition(nom).signe * _lire(etat, nom, identite)
    return total


def _emplois(etat: Etat) -> dict[str, np.ndarray]:
    return {"emplois": _lire(etat, "pib", "emplois") - _signee(etat, EMPLOIS, "emplois")}


def _revenus(etat: Etat) -> dict[str, np.ndarray]:
    return {"revenus": _lire(etat, "pib", "revenus") - _signee(etat, REVENUS, "revenus")}


def _apu(etat: Etat) -> dict[str, np.ndarray]:
    def lu(nom: str) -> np.ndarray:
        return _lire(etat, nom, "apu")

    recettes, depenses = lu("apu_recettes"), lu("apu_depenses_primaires")
    interets, b9 = lu("interets_nets"), lu("b9")
    return {"apu.recettes": recettes - _signee(etat, RECETTES, "apu"),
            "apu.depenses": depenses - _signee(etat, DEPENSES, "apu"),
            "apu.b9": b9 - (recettes - depenses - interets),
            "apu.solde_primaire": lu("solde_primaire") - (b9 + interets)}


def _dette(etat: Etat, precedent: Etat | None = None) -> dict[str, np.ndarray]:
    def lu(nom: str) -> np.ndarray:
        return _lire(etat, nom, "dette")

    ouverture = lu("dette_ouverture")
    out = {"dette": lu("dette") - (ouverture - lu("b9") + lu("sfa")
                                   + lu("ecart_millesime_dette") + lu("ecart_eurostat"))}
    if precedent is not None:
        out["dette.continuite"] = ouverture - _lire(precedent, "dette", "dette")
    return out


def _contributions(etat: Etat) -> dict[str, np.ndarray]:
    pire = np.zeros(etat.n)
    for nom in etat.champs():
        if not REGISTRE[nom].additif:
            continue
        total = np.zeros(etat.n)
        for valeur in etat.contributions[nom].values():
            total = total + valeur
        pire = np.maximum(pire, np.abs(etat[nom] - total))
    return {"contributions": pire}


_CALCULS: dict[str, Callable[..., dict[str, np.ndarray]]] = {
    "emplois": _emplois, "revenus": _revenus, "apu": _apu, "dette": _dette,
    "contributions": _contributions}


def residus(etat: Etat, precedent: Etat | None = None,
            identites: tuple[str, ...] = IDENTITES) -> dict[str, np.ndarray]:
    """Les résidus, en Md€, par identité et sous-identité, sur chaque tirage."""
    out: dict[str, np.ndarray] = {}
    for nom in identites:
        if nom not in _CALCULS:
            raise ValueError(f"identité « {nom} » inconnue ({IDENTITES})")
        calcul = _CALCULS[nom]
        out.update(calcul(etat, precedent) if nom == "dette" else calcul(etat))
    return out


def verifier(etat: Etat, precedent: Etat | None = None,
             identites: tuple[str, ...] = IDENTITES) -> dict[str, np.ndarray]:
    """Refuse l'état si une identité dépasse 1e-9 du PIB sur un tirage ; rend les résidus
    en part du PIB."""
    pib = _lire(etat, "pib", "toutes")
    if np.any(pib <= 0):
        raise IdentiteViolee(f"PIB non positif en {etat.annee} : aucun ratio n'a de sens")
    relatifs = {nom: r / pib for nom, r in residus(etat, precedent, identites).items()}
    for nom, r in relatifs.items():
        pire = int(np.argmax(np.abs(r)))
        if abs(r[pire]) > TOLERANCE:
            raise IdentiteViolee(
                f"identité « {nom} » violée en {etat.annee}, tirage {pire} : "
                f"{r[pire]:+.3e} du PIB ({r[pire] * pib[pire]:+.6f} Md€), tolérance "
                f"{TOLERANCE:g}")
    return relatifs

fichiers.impots/jumeau/impacts/_commun.py:
"""Ce que les dimensions du volet `tableau` partagent (D-606) : l'écart d'un champ de
l'état, sa bande sur les tirages des θ, et le statut que lit une proposition.

Les options que le tableau passe à chaque dimension (`navigateur.Session`, D-605) :

* `trajectoire` : la `Trajectoire` au réglage (un tirage) ; `variante` et `reference` en
  sont les états, année par année ;
* `tirages` : la même trajectoire, vectorisée sur des tirages des θ que le modèle lit,
  chacun selon sa loi (`a_priori`, D-424) : de forme (années, n) ; None si le réglage
  n'en demande pas ;
* `mesures` : les mesures ; `illustratives` : {identifiant : raison} pour celles dont le
  choc est déclaré (une loi hypothétique) ou transformé (`proposition.transformer`) ;
* `mode`, `thetas` (le registre des θ, leur origine dans `loi.origine`), `juge` (ce que
  dit le juge de l'histoire, D-439, `site_jumeau.juge`), `annees` (calculées).
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from typing import Any

import numpy as np

#: Les quantiles de la bande, comme la plage de la page du jumeau (D-459) : 5 et 95 %.
QUANTILES = (5.0, 95.0)


def ecart(reference: Sequence[Any], variante: Sequence[Any], champ: str
          ) -> np.ndarray | None:
    """variante − référence d'un champ, (années, n) ; None s'il manque une année d'un
    côté : absent, jamais zéro."""
    if not all(e.present(champ) for e in (*reference, *variante)):
        return None
    return np.array([np.asarray(v[champ] - r[champ], dtype=float)
                     for r, v in zip(reference, variante, strict=True)])


def niveaux(etats: Sequence[Any], champ: str) -> np.ndarray | None:
    if not all(e.present(champ) for e in etats):
        return None
    return np.array([np.asarray(e[champ], dtype=float) for e in etats])


def serie(f: Any, options: Mapping[str, Any], reference: Sequence[Any],
          variante: Sequence[Any]) -> tuple[np.ndarray, np.ndarray | None,
                                            np.ndarray | None] | None:
    """La valeur au réglage et sa bande (5 et 95 % des tirages) d'un indicateur
    f(reference, variante) -> (années, n) ou None."""
    centre = f(reference, variante)
    if centre is None:
        return None
    valeurs = np.asarray(centre, dtype=float)[:, 0]
    bas = haut = None
    t = options.get("tirages")
    if t is not None and len(t.annees) == len(valeurs):
        x = f(t.reference, t.variante)
        if x is not None and np.asarray(x).shape[1] > 1:
            bas, haut = (np.percentile(np.asarray(x, dtype=float), q, axis=1)
                         for q in QUANTILES)
    return valeurs, bas, haut


def statut(options: Mapping[str, Any]) -> tuple[str, list[str]]:
    """« illustratif » quand une mesure est déclarée ou transformée (son choc n'est pas
    celui d'une passe), sinon « sourcé, non jugé » ; et les limites qui le disent."""
    ill = dict(options.get("illustratives") or {})
    if ill:
        return "illustratif", [f"« {i} » : {r}." for i, r in ill.items()]
    return "sourcé, non jugé", []


def thetas_sans_source(options: Mapping[str, Any]) -> list[str]:
    """Les θ que le modèle lit et dont la loi n'a pas d'estimation publiée (D-417)."""
    return sorted(t["cle"] for t in options.get("thetas") or ()
                  if t.get("lu") and (t.get("loi") or {}).get("origine") in
                  ("large", "magasin"))


def limite_bande(options: Mapping[str, Any]) -> str:
    t = options.get("tirages")
    if t is None:
        return "Sans bande : le réglage n'a pas demandé de tirages des θ."
    n = int(np.asarray(t.variante[0]["pib"]).size)
    return (f"La bande va de 5 à 95 % de {n} tirages des θ que le modèle lit, chacun selon "
            f"sa loi (D-424, D-459) : l'incertitude des réactions de l'économie, pas celle "
            f"du chiffrage de la mesure elle-même.")

fichiers.impots/jumeau/transmission/__init__.py:
"""La carte des effets (but 26, volet `carte`, D-471, D-472) : la fiche de transmission.

UNE FICHE PAR MESURE, un YAML, `transmission/<candidat>/<mesure>.yaml`. Elle dit comment
la mesure se fait et ce qu'elle déclenche, avant tout calcul : le levier, qui paie ou
reçoit d'abord, qui paie au bout, le financement annoncé, les canaux qu'elle ouvre, ses
hypothèses et son montant. Le jumeau la lit (`entree`) : une mesure chiffrée y entre par
son rapport (`Mesure.depuis_rapport`, par la `Session` du navigateur) ; une mesure dont le
candidat énonce un montant y entre comme loi hypothétique (`Mesure.hypothese`), et le
dit ; les autres n'y entrent pas, et la fiche dit ce qui manque.

LE SCHÉMA (version 1). Les sept clés de D-471, plus l'en-tête :

* en-tête : `schema` (1), `mesure` (l'identifiant de `programmes/<candidat>.json`),
  `candidat`, `libelle`, `sorte` et `source` (la citation du programme, son adresse, sa
  date). `sorte` est l'une de :

  - `chiffree` : un rapport d'étude commité porte son coût (`montant.origine: rapport`) ;
  - `hypothese` : le candidat énonce un montant annuel (`declare` du programme), qui
    entre comme loi hypothétique (`montant.origine: hypothese`) ;
  - `parametre` : un paramètre est énoncé (un taux, un âge, un seuil), sans montant ni
    passe : la fiche dit l'assiette qui manque (`montant.origine: aucun`) ;
  - `sans_choc` : une intention, une règle budgétaire, une trajectoire : aucun choc
    (`montant.origine: aucun`).

* `levier` : {`texte` (le texte de droit ou le dispositif touché), `parametre` (le bouton
  du moteur, ou celui que le programme énonce), `valeur`, `enonce` (le paramètre du
  programme, tel quel), `couche` (menages | entreprises, pour une mesure chiffrée)}.
* `payeurs` : une liste de {`qui`, `sens` (paie | recoit), `par` (l'instrument ou
  l'assiette), `note`}. `qui` est l'un de `PAYEURS` : `menages` (les cellules du jumeau ;
  `par`, une variable des cellules quand elle existe, sert de clé par décile),
  `entreprises` (`par`, un impôt du bloc des entreprises ou un instrument du registre),
  `apu:etat`, `apu:secu:<branche>` (maladie, at_mp, vieillesse, famille, autonomie,
  chomage, retraite_complementaire), `apu:apul` (les collectivités), `apu:odac`,
  `reste_du_monde`.
* `incidence` : une liste de {`horizon` (immediat | court | long), `qui`, `texte`,
  `source`} : qui paie au bout. `source` est une référence, ou « non sourcée ».
* `financement` : {`annonce` (le texte du candidat, ou null), `source` (sa citation, ou
  null), `chiffre` (le candidat chiffre-t-il ce financement), `note`}.
* `canaux` : les noms de `jumeau/canaux.py` que la mesure ouvre. Un nom absent du
  registre est un canal attendu d'un autre volet (`CANAUX_ATTENDUS`) : la fiche le garde,
  `valider` le dit, il n'est jamais lu comme ouvert.
* `hypotheses` : une liste de {`texte`, `valeur` (facultative), `source`} ; chaque
  hypothèse a sa source, ou « non sourcée ».
* `montant` : {`origine` (rapport | hypothese | aucun) ; pour un rapport : `scenario`,
  `rapport` ; pour une hypothèse : `annonce` (le montant du candidat, Md€ par an, son sens,
  son horizon, sa source), `chocs` (catégories du compte des APU, Md€ par an en régime,
  signe du moteur : un coût est positif), `profil` (constant | rampe | calendrier : les
  points {année : Md€} que le candidat donne, linéaire entre eux), `debut`, `plein`,
  `fin`, `instrument` (la variante de Mésange la plus proche, ou null), `menages_par`,
  `entreprises_par`, `inclus_dans` (une autre mesure qui le compte déjà) ; pour aucun :
  `manque`}.

LES DONNÉES CRITIQUES (but 27, volet `fiches`, D-504). Deux clés facultatives, écrites
mesure par mesure dans `programmes/fiches/<candidat>.yaml` (et non tirées d'un gabarit) :

* `assiette` : {`texte`, `montant_md` (Md€, ou null), `valeur` et `unite` (un effectif,
  un barème : facultatifs), `annee`, `source`}, ou une liste : ce sur quoi la mesure
  porte et son montant de 2024 à 2026, lu dans une statistique publique (PLF, LFSS,
  comptes de la Sécurité sociale, Insee, DGFiP, Drees). Un nombre d'assiette a toujours
  une source, jamais « non sourcée » ;
* `calendrier` : {`texte`, `source`} : quand la mesure entre en vigueur, selon le candidat.

Un payeur peut dire sa `part` (de 0 à 1) ou, dans `note`, son montant lu dans le rapport.
Le montant d'une hypothèse est celui du candidat (`annonce.par` : `candidat`, par défaut)
ou, quand le candidat donne un paramètre et qu'une assiette publiée le permet, l'assiette
fois le paramètre (`annonce.par` : `calcul`, et `annonce.calcul` : le calcul écrit) ;
la fiche porte alors son `assiette`.

CE QUE LE LECTEUR NE FAIT PAS. Il ne chiffre rien : une fiche ne porte jamais un nombre que
ni un rapport, ni le candidat, ni une assiette publiée (le calcul écrit) ne donne. Une
montée en charge, une clé de répartition, une variante de Mésange approchée sont des
hypothèses déclarées, dites dans la fiche.
"""

from __future__ import annotations

import dataclasses
from collections.abc import Iterable, Mapping, Sequence
from dataclasses import dataclass
from itertools import pairwise
from pathlib import Path
from typing import Any

import yaml

from impots.jumeau.canaux import CANAUX, INSTRUMENTS
from impots.jumeau.champs import SIGNAUX_ENTREPRISES

ICI = Path(__file__).resolve().parent
SCHEMA = 1

SORTES = ("chiffree", "hypothese", "parametre", "sans_choc")
ORIGINES = {"chiffree": "rapport", "hypothese": "hypothese", "parametre": "aucun",
            "sans_choc": "aucun"}
CLES = ("schema", "mesure", "candidat", "libelle", "sorte", "source", "levier",
        "payeurs", "incidence", "financement", "canaux", "hypotheses", "montant")
#: Les clés facultatives des données critiques (D-504).
FACULTATIVES = ("assiette", "calendrier")
HORIZONS = ("immediat", "court", "long")
SENS = ("paie", "recoit")
NON_SOURCEE = "non sourcée"

#: Les branches de la Sécurité sociale (au sens large des ASSO : l'Unédic et les régimes
#: complémentaires en sont, Insee, comptes nationaux, sous-secteur S1314).
BRANCHES = ("maladie", "at_mp", "vieillesse", "famille", "autonomie", "chomage",
            "retraite_complementaire")
PAYEURS = frozenset({"menages", "entreprises", "apu:etat", "apu:apul", "apu:odac",
                     "reste_du_monde", *(f"apu:secu:{b}" for b in BRANCHES)})

#: Les impôts du bloc des entreprises (`champs.SIGNAUX_ENTREPRISES`) et les instruments
#: du registre ; plus ce que paient ou reçoivent les entreprises hors prélèvements.
IMPOTS_ENTREPRISES = frozenset(i for (_, _, ins) in SIGNAUX_ENTREPRISES.values()
                               for i in ins)
PAR_ENTREPRISES = frozenset({*IMPOTS_ENTREPRISES, *INSTRUMENTS, "aides_publiques",
                             "masse_salariale", "prix", "chiffre_affaires", "dividendes",
                             "commande_publique", "autre"})

#: Les catégories du compte des APU qu'un choc déclaré peut toucher (`mesures.CATEGORIES`),
#: relues ici sans importer les mesures (qui importent la chaîne prédictive).
def _categories() -> tuple[str, ...]:
    from impots.jumeau.mesures import CATEGORIES

    return CATEGORIES


#: Les canaux que la carte cite et qu'aucun bloc n'a encore enregistrés dans
#: `jumeau/canaux.py` (D-471). À la jonction (D-487), les noms que `travail` et
#: `financement` ont enregistrés remplacent ceux que la carte proposait :
#: `smic_diffusion`, `incidence_cotisations`, `financement_sous_secteurs`,
#: `compensation_exonerations` et `financement_annonce` gardent leur nom ;
#: `allegements_smic` devient `cout_travail_smic` dans les fiches du Smic (le bloc
#: `travail` y porte la loi, la RGDU et le coût par tranche) et `incidence_cotisations`
#: ailleurs (une exonération change une cotisation employeur, dont le bloc porte
#: l'incidence). Restent attendus ceux qu'aucun volet n'a ouverts. Tant qu'il n'est pas
#: enregistré, un canal n'est pas ouvert.
CANAUX_ATTENDUS: dict[str, tuple[str, str]] = {
    "cout_travail_tranche": ("travail", "le coût du travail et l'emploi par tranche de "
                             "salaire hors d'une hausse du Smic : `travail.emploi_par_"
                             "tranche` le calcule en regard, hors de l'état (D-479)"),
    "offre_travail": ("travail", "l'offre de travail selon le salaire net (marges "
                      "intensive et extensive) : non faite au but 26"),
    "patrimoine_menages": ("aucun volet", "le patrimoine des ménages et sa transmission : "
                           "la population n'en porte pas"),
    "droits_retraite": ("aucun volet", "les âges, les durées et les pensions : la "
                        "population ne vieillit pas en âge"),
}


class TransmissionError(ValueError):
    """Une fiche qui ne se lit pas, ou qui ne peut pas entrer dans le jumeau."""


# --------------------------------------------------------------------------- #
# lire, valider
# --------------------------------------------------------------------------- #
@dataclass(frozen=True)
class Fiche:
    donnees: Mapping[str, Any]
    chemin: Path | None = None

    def __getitem__(self, cle: str) -> Any:
        return self.donnees[cle]

    @property
    def cle(self) -> str:
        return f"{self.donnees['candidat']}/{self.donnees['mesure']}"

    @property
    def sorte(self) -> str:
        return self.donnees["sorte"]

    @property
    def canaux_ouverts(self) -> tuple[str, ...]:
        return tuple(c for c in self.donnees.get("canaux") or () if c in CANAUX)

    @property
    def canaux_attendus(self) -> tuple[str, ...]:
        return tuple(c for c in self.donnees.get("canaux") or () if c not in CANAUX)


def charger(chemin: Path | str) -> Fiche:
    """Une fiche, lue et validée : une fiche invalide est refusée, ses défauts nommés."""
    chemin = Path(chemin)
    d = yaml.safe_load(chemin.read_text(encoding="utf-8"))
    if not isinstance(d, dict):
        raise TransmissionError(f"{chemin} : pas une fiche")
    defauts = valider(d)
    if defauts:
        raise TransmissionError(f"{chemin} : " + " ; ".join(defauts))
    return Fiche(d, chemin)


def fiches(candidat: str | None = None, racine: Path = ICI) -> list[Fiche]:
    """Les fiches d'un candidat (ou toutes), dans l'ordre des noms."""
    motif = f"{candidat}/*.yaml" if candidat else "*/*.yaml"
    return [charger(p) for p in sorted(racine.glob(motif))]


def fiche(candidat: str, mesure: str, racine: Path = ICI) -> Fiche:
    return charger(racine / candidat / f"{mesure}.yaml")


def _source(s: Any) -> bool:
    return isinstance(s, str) and bool(s.strip())


def valider(d: Mapping[str, Any]) -> list[str]:
    """Les défauts d'une fiche, en mots ; une liste vide si elle tient. Un canal attendu
    (absent du registre) n'est pas un défaut : `manques` le dit."""
    out: list[str] = []
    manquent = [c for c in CLES if c not in d]
    if manquent:
        return [f"clés absentes {manquent}"]
    etrangeres = sorted(set(d) - set(CLES) - set(FACULTATIVES))
    if etrangeres:
        out.append(f"clés inconnues {etrangeres}")
    if d["schema"] != SCHEMA:
        out.append(f"schéma {d['schema']} (attendu {SCHEMA})")
    if d["sorte"] not in SORTES:
        out.append(f"sorte « {d['sorte']} » inconnue {SORTES}")
        return out
    src = d["source"] or {}
    if not (_source(src.get("citation")) and _source(src.get("url"))):
        out.append("source du programme sans citation ou sans adresse")
    lev = d["levier"] or {}
    if not _source(lev.get("texte")):
        out.append("levier sans texte")
    for i, p in enumerate(d["payeurs"] or ()):
        if p.get("qui") not in PAYEURS:
            out.append(f"payeur {i} « {p.get('qui')} » inconnu")
        if p.get("sens") not in SENS:
            out.append(f"payeur {i} : sens « {p.get('sens')} » ({SENS})")
        if p.get("qui") == "entreprises" and p.get("par") not in PAR_ENTREPRISES:
            out.append(f"payeur {i} : entreprises par « {p.get('par')} » inconnu")
        part = p.get("part")
        if part is not None and not (isinstance(part, int | float) and 0 <= part <= 1):
            out.append(f"payeur {i} : part « {part} » (de 0 à 1)")
    if d["sorte"] in ("chiffree", "hypothese") and not d["payeurs"]:
        out.append("une mesure qui a un montant sans payeur")
    for i, inc in enumerate(d["incidence"] or ()):
        if inc.get("horizon") not in HORIZONS:
            out.append(f"incidence {i} : horizon « {inc.get('horizon')} » ({HORIZONS})")
        if not _source(inc.get("source")):
            out.append(f"incidence {i} sans source (ou « {NON_SOURCEE} »)")
    for i, h in enumerate(d["hypotheses"] or ()):
        if not (_source(h.get("texte")) and _source(h.get("source"))):
            out.append(f"hypothèse {i} sans texte ou sans source (ou « {NON_SOURCEE} »)")
    fin = d["financement"] or {}
    if "annonce" not in fin:
        out.append("financement sans « annonce » (null s'il est absent)")
    if fin.get("annonce") and not _source(fin.get("source")):
        out.append("financement annoncé sans sa citation")
    mal = [c for c in d["canaux"] or () if c not in CANAUX and c not in CANAUX_ATTENDUS]
    if mal:
        out.append(f"canaux ni enregistrés ni attendus {mal}")
    out.extend(_valider_donnees(d))
    out.extend(_valider_montant(d["sorte"], d["montant"] or {}))
    a = (d["montant"] or {}).get("annonce") or {}
    if a.get("par") == "calcul" and not any(chiffree(x) for x in assiettes(d)):
        out.append("montant calculé sans assiette chiffrée")
    return out


def chiffree(x: Mapping[str, Any]) -> bool:
    """Une assiette qui porte un nombre : un montant ou une valeur (D-504)."""
    return any(isinstance(x.get(k), int | float) and not isinstance(x.get(k), bool)
               for k in ("montant_md", "valeur"))


def assiettes(d: Mapping[str, Any]) -> list[Mapping[str, Any]]:
    """Les assiettes d'une fiche (D-504), en liste."""
    a = d.get("assiette")
    if a is None:
        return []
    return list(a) if isinstance(a, list) else [a]


def _valider_donnees(d: Mapping[str, Any]) -> list[str]:
    out: list[str] = []
    a = d.get("assiette")
    if a is not None and not isinstance(a, dict | list):
        return ["assiette ni table ni liste"]
    for i, x in enumerate(assiettes(d)):
        if not (isinstance(x, dict) and _source(x.get("texte")) and _source(x.get("source"))):
            out.append(f"assiette {i} sans texte ou sans source")
            continue
        for k in ("montant_md", "valeur"):
            v = x.get(k)
            if v is not None and not isinstance(v, int | float):
                out.append(f"assiette {i} : {k} « {v} » pas un nombre")
        if x.get("valeur") is not None and not _source(x.get("unite")):
            out.append(f"assiette {i} : une valeur sans unité")
        if chiffree(x) and x["source"] == NON_SOURCEE:
            out.append(f"assiette {i} : un montant sans source")
    cal = d.get("calendrier")
    if cal is not None and not (isinstance(cal, dict) and _source(cal.get("texte"))
                                and _source(cal.get("source"))):
        out.append("calendrier sans texte ou sans source")
    return out


def _valider_montant(sorte: str, m: Mapping[str, Any]) -> list[str]:
    out: list[str] = []
    origine = m.get("origine")
    if origine != ORIGINES[sorte]:
        return [f"sorte « {sorte} » et montant d'origine « {origine} »"]
    if origine == "rapport":
        if not (m.get("scenario") and m.get("rapport")):
            out.append("montant d'un rapport sans scénario ou sans rapport")
    elif origine == "hypothese":
        a = m.get("annonce") or {}
        if not (a.get("montant_md") and a.get("sens") and _source(a.get("citation"))):
            out.append("hypothèse sans montant annoncé, sens ou citation")
        if a.get("par", "candidat") not in ("candidat", "calcul"):
            out.append(f"montant par « {a.get('par')} » (candidat | calcul)")
        if a.get("par") == "calcul" and not _source(a.get("calcul")):
            out.append("montant calculé sans son calcul écrit")
        chocs = m.get("chocs") or {}
        if not chocs:
            out.append("hypothèse sans chocs")
        inconnues = sorted(set(chocs) - set(_categories()))
        if inconnues:
            out.append(f"chocs sur des catégories inconnues {inconnues}")
        if m.get("profil") not in ("constant", "rampe", "calendrier"):
            out.append(f"profil « {m.get('profil')} » (constant | rampe | calendrier)")
        if m.get("profil") == "calendrier" and not m.get("calendrier"):
            out.append("profil « calendrier » sans calendrier {année : Md€}")
        if not (isinstance(m.get("debut"), int) and isinstance(m.get("fin"), int)
                and m["debut"] <= m.get("plein", m["debut"]) <= m["fin"]):
            out.append("années de l'hypothèse (debut ≤ plein ≤ fin) absentes")
        if m.get("instrument") not in (None, *INSTRUMENTS):
            out.append(f"instrument « {m.get('instrument')} » inconnu")
        if m.get("entreprises_par") not in (None, *IMPOTS_ENTREPRISES):
            out.append(f"entreprises_par « {m.get('entreprises_par')} » inconnu")
    elif not _source(m.get("manque")):
        out.append("montant absent sans dire ce qui manque")
    return out


def manques(f: Fiche) -> list[str]:
    """Ce qui manque à une fiche pour que la mesure se propage, en mots : les canaux pas
    encore enregistrés, les hypothèses non sourcées, l'incidence non sourcée, le montant
    absent, le financement non chiffré."""
    d, out = f.donnees, []
    for c in f.canaux_attendus:
        volet, porte = CANAUX_ATTENDUS[c]
        out.append(f"canal « {c} » ({porte}) : pas encore dans le registre, volet {volet}")
    ns = [h["texte"] for h in d["hypotheses"] or () if h["source"] == NON_SOURCEE]
    if ns:
        out.append(f"{len(ns)} hypothèse(s) non sourcée(s)")
    if any(i["source"] == NON_SOURCEE for i in d["incidence"] or ()):
        out.append("une incidence non sourcée")
    if d["montant"]["origine"] == "aucun":
        out.append(f"aucun montant : {d['montant']['manque']}")
    if d["financement"].get("annonce") is None and d["sorte"] != "sans_choc":
        out.append("aucun financement annoncé")
    return out


# --------------------------------------------------------------------------- #
# le lien au jumeau
# --------------------------------------------------------------------------- #
@dataclass(frozen=True)
class Entree:
    """Ce que le jumeau lit d'une fiche : la `Mesure` (ou None, et pourquoi), les canaux
    ouverts et attendus, les hypothèses déclarées."""

    fiche: Fiche
    mesure: Any | None
    refus: str | None
    canaux: tuple[str, ...]
    attendus: tuple[str, ...]
    hypotheses: tuple[Mapping[str, Any], ...]


def annuel(m: Mapping[str, Any], annees: Sequence[int]) -> dict[int, float]:
    """La part du montant de régime, chaque année : 1 de `debut` à `fin` (constant) ; une
    rampe linéaire de `debut` à `plein`, puis 1 jusqu'à `fin` ; ou le calendrier du
    candidat, linéaire entre ses points, son dernier point étant le régime."""
    debut, fin = int(m["debut"]), int(m["fin"])
    plein = int(m.get("plein", debut))
    out = {}
    if m["profil"] == "calendrier":
        pts = sorted((int(a), float(v)) for a, v in m["calendrier"].items())
        regime = pts[-1][1]
        for a in annees:
            if a < pts[0][0] or a > fin:
                continue
            v = pts[-1][1]
            for (a0, v0), (a1, v1) in pairwise(pts):
                if a0 <= a <= a1:
                    v = v0 + (v1 - v0) * (a - a0) / (a1 - a0)
                    break
            out[a] = v / regime
        return out
    for a in annees:
        if a < debut or a > fin:
            continue
        out[a] = (1.0 if m["profil"] == "constant" or a >= plein
                  else (a - debut + 1) / (plein - debut + 1))
    return out


def hypothese(f: Fiche, *, tables: Mapping[str, Any] | None = None,
              cellules: Any = None, annees: Sequence[int] = range(2026, 2036)) -> Any:
    """La loi hypothétique d'une fiche `hypothese` (`Mesure.hypothese`) : ses chocs au
    compte des APU, son impulsion sur la variante de Mésange la plus proche quand la
    fiche en nomme une et que les tables la portent, et ses chocs aux ménages (au
    prorata de `menages_par` dans les cellules) et aux entreprises (`entreprises_par`),
    comme `navigateur.Session.hypothese`."""
    from impots.jumeau.comparaison import _parts
    from impots.jumeau.mesures import Mesure

    m = f["montant"]
    if f.sorte != "hypothese":
        raise TransmissionError(f"{f.cle} : sorte « {f.sorte} », pas une hypothèse")
    parts = annuel(m, annees)
    if not parts:
        raise TransmissionError(f"{f.cle} : aucune année de {m['debut']} à {m['fin']} "
                                f"dans {annees[0]}–{annees[-1]}")
    chocs = {a: {c: float(v) * s for c, v in m["chocs"].items()} for a, s in parts.items()}
    cout = {a: sum(c.values()) for a, c in chocs.items()}
    instrument = m.get("instrument")
    couvert = bool(instrument and tables and instrument in tables.get("instruments", {}))
    macro = ({"horizons": tables["horizons"], "court": tables["court"],
              "instruments": {instrument: tables["instruments"][instrument]}}
             if couvert else None)
    mesure = Mesure.hypothese(
        f"{f['candidat']}_{f['mesure']}", f"{f['libelle']} (déclaré par le candidat)",
        chocs=chocs, impulsions=({a: {instrument: v} for a, v in cout.items()}
                                 if couvert else None),
        macro=macro, auteur=f["candidat"])
    menages = entreprises = None
    if m.get("menages_par") and cellules is not None:
        cle = _parts(cellules.par_decile(m["menages_par"]))
        part = float(m.get("menages_part", 1.0))
        menages = {a: {"deciles": [part * v * x for x in cle]} for a, v in cout.items()}
    if m.get("entreprises_par"):
        entreprises = {a: {m["entreprises_par"]: -v} for a, v in cout.items()}
    return dataclasses.replace(mesure, menages=menages, entreprises=entreprises)


def entree(f: Fiche, session: Any, *, vue: str = "vieillie",
           convention: str | None = None, mode: str = "reduit") -> Entree:
    """Ce que le jumeau lit d'une fiche. `session` est une `navigateur.Session` : une
    mesure chiffrée y est lue par son rapport (`Session.mesure`, donc
    `Mesure.depuis_rapport`) ; une hypothèse par `hypothese`, avec les tables de Mésange
    et les cellules de la session."""
    d = f.donnees
    commun = {"fiche": f, "canaux": f.canaux_ouverts, "attendus": f.canaux_attendus,
              "hypotheses": tuple(d["hypotheses"] or ())}
    origine = d["montant"]["origine"]
    if origine == "rapport":
        scenario = d["montant"]["scenario"]
        if scenario not in session.candidats:
            return Entree(mesure=None, refus=f"rapport « {scenario} » absent des entrées "
                          f"du jumeau", **commun)
        return Entree(mesure=_lire(session, scenario, vue, convention, mode), refus=None,
                      **commun)
    if origine == "hypothese":
        if d["montant"].get("inclus_dans"):
            return Entree(mesure=None, refus=f"compté dans « {d['montant']['inclus_dans']} »"
                          f", que le candidat ne ventile pas : ne pas additionner",
                          **commun)
        return Entree(mesure=hypothese(f, tables=session.tables,
                                       cellules=session.cellules),
                      refus=None, **commun)
    return Entree(mesure=None, refus=d["montant"]["manque"], **commun)


def _lire(session: Any, scenario: str, vue: str, convention: str | None,
          mode: str) -> Any:
    """Le rapport d'une mesure : en mode structurel, la mesure que ce mode lit
    (`Session.mesure_structurel` : une hausse du Smic par le bloc `travail`, D-487)."""
    if mode == "structurel":
        return session.mesure_structurel(scenario, vue, convention)
    return session.mesure(scenario, vue, convention)


def programme(candidat: str, session: Any, *, vue: str = "vieillie",
              convention: str | None = None, racine: Path = ICI, mode: str = "reduit"
              ) -> tuple[list[Entree], list[Entree]]:
    """Les mesures d'un programme prêtes à entrer, et les autres.

    La part chiffrée entre par le rapport du programme (`pres2027_<candidat>_programme`),
    qui fait tourner ses mesures chiffrées ensemble, en interaction, et non par la somme
    de leurs rapports ; une mesure chiffrée seule n'est donc pas rajoutée. Les hypothèses
    entrent chacune par sa loi, sauf celles qu'une autre mesure compte déjà."""
    toutes = fiches(candidat, racine)
    if not toutes:
        raise TransmissionError(f"aucune fiche pour « {candidat} »")
    pretes: list[Entree] = []
    autres: list[Entree] = []
    scen = f"pres2027_{candidat}_programme"
    chiffrees = [f for f in toutes if f.sorte == "chiffree"]
    if chiffrees:
        if scen not in session.candidats:
            raise TransmissionError(f"rapport du programme « {scen} » absent")
        tete = chiffrees[0]
        canaux = tuple(dict.fromkeys(c for f in chiffrees for c in f.canaux_ouverts))
        attendus = tuple(dict.fromkeys(c for f in chiffrees for c in f.canaux_attendus))
        hyp = tuple(h for f in chiffrees for h in f["hypotheses"] or ())
        pretes.append(Entree(fiche=tete, mesure=_lire(session, scen, vue, convention, mode),
                             refus=None, canaux=canaux, attendus=attendus,
                             hypotheses=hyp))
    for f in toutes:
        if f.sorte == "chiffree":
            continue
        e = entree(f, session, vue=vue, convention=convention, mode=mode)
        (pretes if e.mesure is not None else autres).append(e)
    return pretes, autres


def qualite(racine: Path = ICI, candidats: Iterable[str] | None = None
            ) -> dict[str, dict[str, int]]:
    """{candidat : compte} des données critiques (D-505) : les fiches par sorte, les
    hypothèses chiffrées par le candidat et par le calcul, les fiches sans montant, celles
    qui portent une assiette chiffrée, et les hypothèses sourcées et non sourcées ; et
    (D-510) celles qui disent leur calendrier, et celles dont chaque APU qui paie a sa
    part (que le compte des sous-secteurs lit, `financement.comptes.cle_reste`)."""
    out: dict[str, dict[str, int]] = {}
    for f in fiches(None, racine):
        c = f["candidat"]
        if candidats is not None and c not in candidats:
            continue
        q = out.setdefault(c, {**dict.fromkeys(SORTES, 0), "hypothese_candidat": 0,
                               "hypothese_calcul": 0, "sans_montant": 0,
                               "assiette_chiffree": 0, "calendrier": 0,
                               "parts_payeurs": 0, "hypotheses_sourcees": 0,
                               "hypotheses_non_sourcees": 0})
        q[f.sorte] += 1
        m = f["montant"]
        if f.sorte == "hypothese":
            par = (m.get("annonce") or {}).get("par", "candidat")
            q[f"hypothese_{par}"] += 1
        if m["origine"] == "aucun" and f.sorte == "parametre":
            q["sans_montant"] += 1
        if any(chiffree(x) for x in assiettes(f.donnees)):
            q["assiette_chiffree"] += 1
        if f.donnees.get("calendrier"):
            q["calendrier"] += 1
        apu = [p for p in f["payeurs"] or () if str(p.get("qui", "")).startswith("apu:")
               and p.get("sens") == "paie"]
        if apu and all(p.get("part") is not None for p in apu):
            q["parts_payeurs"] += 1
        for h in f["hypotheses"] or ():
            q["hypotheses_non_sourcees" if h["source"] == NON_SOURCEE
              else "hypotheses_sourcees"] += 1
    return out


def releve(racine: Path = ICI, candidats: Iterable[str] | None = None
           ) -> dict[str, dict[str, int]]:
    """{candidat : {sorte : nombre de fiches}}, et les canaux attendus cités."""
    out: dict[str, dict[str, int]] = {}
    for f in fiches(None, racine):
        c = f["candidat"]
        if candidats is not None and c not in candidats:
            continue
        out.setdefault(c, dict.fromkeys(SORTES, 0))[f.sorte] += 1
    return out
